#define TEST_L3(_b) _Generic((_b), \
		struct ii_pb *: test_pb_ip4, \
		default: test_pkt_ip4)(_b)
#define TEST_L4(_b) _Generic((_b), \
		struct ii_pb *: test_pb_l4, \
		default: test_pkt_l4)(_b)
#define PB_IP4(_b) TEST_L3(_b)
#define PB_IP4_HDR_LEN(_b) ((PB_IP4(_b)->vl & 0x0f) << 2)
#define PB_IP4_TOTAL_LEN(_b) (ii_ntohs(PB_IP4(_b)->len_be))
#define PB_ARP(_b) ((struct iip_arp_hdr *)TEST_L4(_b))
#define PB_ARP_HW_SENDER(_b) ((uint8_t *)PB_ARP(_b) + sizeof(struct iip_arp_hdr))
#define PB_ARP_IP_SENDER(_b) (PB_ARP_HW_SENDER(_b) + PB_ARP(_b)->lhw)
#define PB_ARP_HW_TARGET(_b) (PB_ARP_IP_SENDER(_b) + PB_ARP(_b)->lproto)
#define PB_ARP_IP_TARGET(_b) (PB_ARP_HW_TARGET(_b) + PB_ARP(_b)->lhw)
#define PB_ICMP(_b) ((struct iip_icmp_hdr *)TEST_L4(_b))
#define PB_ICMP_DATA(_b) ((uint8_t *)PB_ICMP(_b) + sizeof(struct iip_icmp_hdr))
#define PB_TCP(_b) ((struct iip_tcp_hdr *)TEST_L4(_b))
#define PB_TCP_HDR_LEN(_b) \
	(((uint16_t)ii_ntohs(PB_TCP(_b)->flags)) >> 12)
#define PB_TCP_HDR_HAS_FIN(_b) ((ii_ntohs(PB_TCP(_b)->flags) & 0x01U) != 0)
#define PB_TCP_HDR_HAS_SYN(_b) ((ii_ntohs(PB_TCP(_b)->flags) & 0x02U) != 0)
#define PB_TCP_HDR_HAS_RST(_b) ((ii_ntohs(PB_TCP(_b)->flags) & 0x04U) != 0)
#define PB_TCP_HDR_HAS_PSH(_b) ((ii_ntohs(PB_TCP(_b)->flags) & 0x08U) != 0)
#define PB_TCP_HDR_HAS_ACK(_b) ((ii_ntohs(PB_TCP(_b)->flags) & 0x10U) != 0)
#define PB_TCP_HDR_HAS_URG(_b) ((ii_ntohs(PB_TCP(_b)->flags) & 0x20U) != 0)
#define PB_TCP_HDR_HAS_ECE(_b) ((ii_ntohs(PB_TCP(_b)->flags) & 0x40U) != 0)
#define PB_TCP_HDR_HAS_CWR(_b) ((ii_ntohs(PB_TCP(_b)->flags) & 0x80U) != 0)
#define PB_TCP_HDR_SET_LEN(_b, _l) do { \
	PB_TCP(_b)->flags = ii_htons(((_l) << 12) | \
			(ii_ntohs(PB_TCP(_b)->flags) & 0xffU)); \
} while (0)
#define PB_TCP_HDR_SET_FLAGS(_b, _f) do { \
	PB_TCP(_b)->flags = (PB_TCP(_b)->flags & ii_htons(~0xffU)) | \
			ii_htons(_f); \
} while (0)
#define PB_TCP_PAYLOAD(_b) ((uint8_t *)PB_TCP(_b) + PB_TCP_HDR_LEN(_b) * 4)
#define PB_TCP_PAYLOAD_LEN(_b) ((uint16_t)(PB_IP4_TOTAL_LEN(_b) - \
		PB_IP4_HDR_LEN(_b) - PB_TCP_HDR_LEN(_b) * 4))
#define PB_TCP_OPT(_b) ((uint8_t *)PB_TCP(_b) + sizeof(struct iip_tcp_hdr))
#define PB_TCP_OPTLEN(_b) \
	(PB_TCP_HDR_LEN(_b) * 4 - sizeof(struct iip_tcp_hdr))
#define PB_UDP(_b) ((struct iip_udp_hdr *)TEST_L4(_b))
#define PB_UDP_PAYLOAD(_b) ((uint8_t *)PB_UDP(_b) + sizeof(struct iip_udp_hdr))
#define PB_UDP_TOTAL_LEN(_b) (ii_ntohs(PB_UDP(_b)->len_be))
#define PB_UDP_PAYLOAD_LEN(_b) \
	((uint16_t)(PB_UDP_TOTAL_LEN(_b) - sizeof(struct iip_udp_hdr)))


static uint8_t _iss_key[32];
static const uint8_t _fastopen_key[32] = {
	0x54, 0x46, 0x4f, 0x2d, 0x49, 0x49, 0x50, 0x2d,
	0x54, 0x45, 0x53, 0x54, 0x2d, 0x4b, 0x45, 0x59,
	0x54, 0x46, 0x4f, 0x2d, 0x49, 0x49, 0x50, 0x2d,
	0x54, 0x45, 0x53, 0x54, 0x2d, 0x4b, 0x45, 0x59,
};
static uint8_t _fastopen_cookie_len = 16;
static struct {
	uint32_t peer_ip4_be;
	uint32_t local_ip4_be;
	uint8_t len;
	uint8_t buf[16];
} _fastopen_saved_cookie;

static void test_tcp_fastopen_request(uint32_t ip_s, uint32_t ip_d,
		uint8_t *cookie, uint8_t *cookie_len)
{
	uint8_t connection_id[8];
	int ret;

	if (!_fastopen_cookie_len) {
		*cookie_len = 0;
		return;
	}
	memcpy(&connection_id[0], &ip_s, sizeof(ip_s));
	memcpy(&connection_id[4], &ip_d, sizeof(ip_d));
	ret = blake2s(cookie, _fastopen_cookie_len,
			connection_id, sizeof(connection_id),
			_fastopen_key, sizeof(_fastopen_key));
	assert(ret == 0);
	*cookie_len = _fastopen_cookie_len;
}

static uint8_t test_tcp_fastopen_cookie_matches(uint32_t ip_s, uint32_t ip_d,
		const uint8_t *cookie, uint8_t cookie_len)
{
	uint8_t expected[sizeof(_fastopen_saved_cookie.buf)];
	uint8_t expected_len;
	uint8_t difference;
	unsigned int i;

	test_tcp_fastopen_request(ip_s, ip_d, expected, &expected_len);
	difference = expected_len ^ cookie_len;
	if (cookie_len != expected_len)
		return 0;
	for (i = 0; i < expected_len; i++)
		difference |= expected[i] ^ cookie[i];
	return difference == 0;
}

static long test_tcp_fastopen_check(uint32_t ip_s, uint32_t ip_d,
		const uint8_t *cookie, uint8_t cookie_len)
{
	if (test_tcp_fastopen_cookie_matches(ip_s, ip_d, cookie, cookie_len))
		return 0;

	/*
	 * A cookie carried by a SYN+ACK was generated for the opposite packet
	 * direction.  Preserve it for a later active Fast Open while returning
	 * failure here: it authenticates the client/server pair, not this
	 * server-to-client segment.
	 */
	if (test_tcp_fastopen_cookie_matches(ip_d, ip_s, cookie, cookie_len)) {
		_fastopen_saved_cookie.peer_ip4_be = ip_s;
		_fastopen_saved_cookie.local_ip4_be = ip_d;
		_fastopen_saved_cookie.len = cookie_len;
		memcpy(_fastopen_saved_cookie.buf, cookie, cookie_len);
	}
	return -1;
}

static uint32_t iip_ops_tcp_iss_off(uint32_t _src_ip, uint32_t _dst_ip, uint16_t _src_port, uint16_t _dst_port)
{
	uint8_t connection_id[12];
	uint8_t out[BLAKE2S_OUTBYTES];
	size_t out_len = BLAKE2S_OUTBYTES;
	int ret;

	/* Hash an explicitly serialized network-order 4-tuple. */
	memcpy(&connection_id[0], &_src_ip, sizeof(_src_ip));
	memcpy(&connection_id[4], &_dst_ip, sizeof(_dst_ip));
	memcpy(&connection_id[8], &_src_port, sizeof(_src_port));
	memcpy(&connection_id[10], &_dst_port, sizeof(_dst_port));
	ret = blake2s(out, out_len, connection_id, sizeof(connection_id),
			_iss_key, sizeof(_iss_key));
	assert(ret == 0);
	return ((uint32_t)out[0] << 24) | ((uint32_t)out[1] << 16) |
		((uint32_t)out[2] << 8) | out[3];
}

