/* Fields of a SYN,ACK sent in response to a passive open. */
struct passive_syn_ack {
	struct ii_tcp_conn *conn;
	uint32_t iss;
	uint16_t window;
	int has_ws;
	uint8_t ws_shift;
	int has_ts;
	uint32_t ts_val;
};

/*
 * Deliver a SYN from peer_port with the requested options (ws_shift < 0
 * means no Window Scale option; ts nonzero adds a Timestamps option) and
 * record the SYN,ACK.  When establish is set, complete the handshake.
 */
static int fixture_passive_open(struct fixture *f, uint16_t peer_port_be,
		int ws_shift, int ts, int establish, struct passive_syn_ack *out)
{
	struct tcp_packet_spec spec;
	void *syn_ack = NULL;
	unsigned int i;

	memset(out, 0, sizeof(*out));
	fixture_incoming_spec(f, &spec, 100, NULL, 0);
	spec.src_port_be = peer_port_be;
	spec.tcp_flags = TEST_TCP_SYN;
	spec.window = 65535;
	tcp_packet_add_mss(&spec, 1460);
	if (ws_shift >= 0) {
		uint8_t shift = (uint8_t)ws_shift;
		tcp_packet_add_option(&spec, 3, &shift, 1);
	}
	if (ts) {
		uint8_t value[8] = { 0, 0, 0x10, 0, 0, 0, 0, 0 };
		tcp_packet_add_option(&spec, 8, value, sizeof(value));
	}
	fixture_deliver(f, build_tcp_packet(&spec, &f->state));
	fixture_run_timers(f);
	for (i = 0; i < f->state.out_cnt; i++) {
		void *pkt = f->state.out[i];
		if (PB_IP4(pkt)->proto == 6 && PB_TCP_HDR_HAS_SYN(pkt) &&
				PB_TCP_HDR_HAS_ACK(pkt) &&
				PB_TCP(pkt)->dst_be == peer_port_be)
			syn_ack = pkt;
	}
	out->conn = fixture_find_peer_port(f, peer_port_be);
	if (!syn_ack || !out->conn)
		return 0;
	out->iss = ii_ntohl(PB_TCP(syn_ack)->seq_be);
	out->window = ii_ntohs(PB_TCP(syn_ack)->win_be);
	{
		uint8_t *ws = option_find(syn_ack, 3);
		uint8_t *tsopt = option_find(syn_ack, 8);
		out->has_ws = ws && ws[1] == 3;
		out->ws_shift = out->has_ws ? ws[2] : 0;
		out->has_ts = tsopt && tsopt[1] == 10;
		if (out->has_ts)
			out->ts_val = (uint32_t)tsopt[2] << 24 | (uint32_t)tsopt[3] << 16 |
				(uint32_t)tsopt[4] << 8 | tsopt[5];
	}
	free_output(&f->state);
	if (!establish)
		return 1;
	fixture_incoming_spec(f, &spec, 101, NULL, 0);
	spec.src_port_be = peer_port_be;
	spec.ack_seq = out->iss + 1;
	spec.window = 65535;
	if (ts && out->has_ts) {
		uint8_t value[8] = { 0, 0, 0x10, 1,
			(uint8_t)(out->ts_val >> 24), (uint8_t)(out->ts_val >> 16),
			(uint8_t)(out->ts_val >> 8), (uint8_t)out->ts_val };
		tcp_packet_add_option(&spec, 8, value, sizeof(value));
	}
	fixture_deliver(f, build_tcp_packet(&spec, &f->state));
	fixture_run_timers(f);
	free_output(&f->state);
	return out->conn->state == II_TCP_STATE_ESTABLISHED;
}

/*
 * RFC 7323 Section 2.2: a TCP may send the Window Scale option in a
 * SYN,ACK only if it received the option in the initial SYN.
 */
static enum result test_tcp_ws_not_offered(const char **why)
{
	struct fixture f;
	struct passive_syn_ack syn_ack;

	if (!fixture_init(&f) ||
			!fixture_passive_open(&f, ii_htons(27000), -1, 0, 0, &syn_ack))
		return RESULT_FAIL;
	if (syn_ack.has_ws) {
		*why = "SYN,ACK carried Window Scale although the SYN did not";
		return RESULT_FAIL;
	}
	return RESULT_PASS;
}

/*
 * RFC 7323 Sections 2.2 and 2.3: once both SYNs carry the option, every
 * window field sent after the SYN,ACK is interpreted by the peer as
 * field << (the shift announced in the SYN,ACK).  The shift announced for
 * the local receive side is chosen locally, not copied from the peer, and
 * the window it implies must not exceed what the receive buffer can hold.
 * The peer offers the maximum shift, 14, to expose a copied value.
 */
static enum result test_tcp_ws_negotiated_window(const char **why)
{
	static const uint8_t payload[1] = { 0 };
	struct fixture f;
	struct tcp_packet_spec spec;
	struct passive_syn_ack syn_ack;
	const uint16_t peer_port_be = ii_htons(27001);
	void *ack = NULL;
	uint64_t implied;
	unsigned int i;

	if (!fixture_init(&f) ||
			!fixture_passive_open(&f, peer_port_be, 14, 0, 1, &syn_ack))
		return RESULT_FAIL;
	if (!syn_ack.has_ws)
		return RESULT_PASS; /* declining window scaling is permitted */
	if (syn_ack.ws_shift > 14) {
		*why = "SYN,ACK announced a window shift larger than 14";
		return RESULT_FAIL;
	}
	fixture_incoming_spec(&f, &spec, 101, payload, sizeof(payload));
	spec.src_port_be = peer_port_be;
	spec.ack_seq = syn_ack.iss + 1;
	spec.window = 65535;
	f.state.accept_arbitrary_payload = 1;
	fixture_deliver(&f, build_tcp_packet(&spec, &f.state));
	for (i = 0; i < 50 && !ack; i++) {
		unsigned int k;
		for (k = 0; k < f.state.out_cnt; k++) {
			void *pkt = f.state.out[k];
			if (PB_IP4(pkt)->proto == 6 && PB_TCP_HDR_HAS_ACK(pkt) &&
					PB_TCP(pkt)->dst_be == peer_port_be &&
					ii_ntohl(PB_TCP(pkt)->ack_seq_be) == 102)
				ack = pkt;
		}
		if (!ack) {
			free_output(&f.state);
			fake_clock_advance_ms(&f.state, 10);
			fixture_run_timers(&f);
		}
	}
	if (!ack) {
		*why = "received data was not acknowledged";
		return RESULT_FAIL;
	}
	implied = (uint64_t)ii_ntohs(PB_TCP(ack)->win_be) << syn_ack.ws_shift;
	if (implied > syn_ack.conn->buf.capacity) {
		*why = "the window implied by the announced shift exceeds the receive buffer";
		return RESULT_FAIL;
	}
	return RESULT_PASS;
}

struct test_summary {
	unsigned int failed;
	unsigned int skipped;
	unsigned int todo;
};

static void report_requirement_result(unsigned int index, enum result result,
		const char *why, struct test_summary *summary)
{
	const struct requirement_test *test = &requirement_tests[index];
	unsigned int number = index + 1;

	if (result == RESULT_PASS) {
		printf("ok %u - MUST-%u [RFC 9293 \xc2\xa7%s] %s\n",
				number, number, rfc9293_requirement_sections[index],
				test->description);
	} else if (result == RESULT_SKIP) {
		printf("ok %u - MUST-%u [RFC 9293 \xc2\xa7%s] %s # SKIP %s\n",
				number, number, rfc9293_requirement_sections[index],
				test->description, why);
		summary->skipped++;
	} else {
		printf("not ok %u - MUST-%u [RFC 9293 \xc2\xa7%s] %s%s%s\n",
				number, number, rfc9293_requirement_sections[index],
				test->description, why ? " - " : "", why ? why : "");
		summary->failed++;
	}
	fflush(stdout);
}

static int rfc9293_test_main(void)
{
	struct test_summary summary = { 0 };
	unsigned int i;

	rfc9293_section_mapping_self_test();
	printf("TAP version 13\n1..%zu\n", ARRAY_LENGTH(requirement_tests));
	fflush(stdout);
	for (i = 0; i < ARRAY_LENGTH(requirement_tests); i++) {
		const char *why = NULL;
		enum result result = run_isolated_test(requirement_tests[i].run, &why);

		report_requirement_result(i, result, why, &summary);
	}
	fprintf(stderr,
		"RFC 9293 mapped-test summary (not a complete conformance proof): "
		"%u passed, %u failed, %u skipped\n",
		RFC9293_REQUIREMENT_COUNT - summary.failed - summary.skipped,
		summary.failed, summary.skipped);
	return summary.failed ? EXIT_FAILURE : EXIT_SUCCESS;
}

static int requirement_suite_main(const char *name,
		const struct ip4_requirement_test *tests, size_t count)
{
	struct test_summary summary = { 0 };
	unsigned int i;

	printf("TAP version 13\n1..%zu\n", count);
	fflush(stdout);
	for (i = 0; i < count; i++) {
		const struct ip4_requirement_test *test = &tests[i];
		const char *why = NULL;
		enum result result = run_isolated_test(test->run, &why);

		if (result == RESULT_PASS) {
			printf("ok %u - %s %s\n", i + 1, test->id,
					test->description);
		} else if (result == RESULT_SKIP) {
			printf("ok %u - %s %s # SKIP %s\n", i + 1,
					test->id, test->description, why);
			summary.skipped++;
		} else if (result == RESULT_TODO) {
			printf("not ok %u - %s %s # TODO %s\n", i + 1,
					test->id, test->description,
					why ? why : "recommended behavior is not implemented");
			summary.todo++;
		} else {
			printf("not ok %u - %s %s%s%s\n", i + 1, test->id,
					test->description, why ? " - " : "",
					why ? why : "");
			summary.failed++;
		}
		fflush(stdout);
	}
	fprintf(stderr,
			"%s summary: %zu passed, %u failed, %u skipped, %u todo\n",
			name, count - summary.failed - summary.skipped - summary.todo,
			summary.failed, summary.skipped, summary.todo);
	return summary.failed ? EXIT_FAILURE : EXIT_SUCCESS;
}

/* Deliver one data octet at sequence 101 and return the ACK for it. */
static void *passive_data_ack(struct fixture *f, uint16_t peer_port_be,
		const struct passive_syn_ack *syn_ack, const uint8_t *ts_option)
{
	static const uint8_t payload[1] = { 0 };
	struct tcp_packet_spec spec;
	unsigned int i, k;

	fixture_incoming_spec(f, &spec, 101, payload, sizeof(payload));
	spec.src_port_be = peer_port_be;
	spec.ack_seq = syn_ack->iss + 1;
	spec.window = 65535;
	if (ts_option)
		tcp_packet_add_option(&spec, 8, ts_option, 8);
	f->state.accept_arbitrary_payload = 1;
	fixture_deliver(f, build_tcp_packet(&spec, &f->state));
	for (i = 0; i < 50; i++) {
		for (k = 0; k < f->state.out_cnt; k++) {
			void *pkt = f->state.out[k];
			if (PB_IP4(pkt)->proto == 6 && PB_TCP_HDR_HAS_ACK(pkt) &&
					PB_TCP(pkt)->dst_be == peer_port_be &&
					ii_ntohl(PB_TCP(pkt)->ack_seq_be) == 102)
				return pkt;
		}
		free_output(&f->state);
		fake_clock_advance_ms(&f->state, 10);
		fixture_run_timers(f);
	}
	return NULL;
}

/*
 * RFC 7323 Section 3.2: a TCP may send the Timestamps option in segments
 * other than the initial SYN only if it received the option in the initial
 * SYN for the connection.
 */
static enum result test_tcp_ts_not_offered(const char **why)
{
	struct fixture f;
	struct passive_syn_ack syn_ack;
	const uint16_t peer_port_be = ii_htons(27100);
	void *ack;

	if (!fixture_init(&f) ||
			!fixture_passive_open(&f, peer_port_be, -1, 0, 1, &syn_ack))
		return RESULT_FAIL;
	if (syn_ack.has_ts) {
		*why = "SYN,ACK carried Timestamps although the SYN did not";
		return RESULT_FAIL;
	}
	ack = passive_data_ack(&f, peer_port_be, &syn_ack, NULL);
	if (!ack) {
		*why = "received data was not acknowledged";
		return RESULT_FAIL;
	}
	if (option_find(ack, 8)) {
		*why = "a data ACK carried Timestamps although they were not negotiated";
		return RESULT_FAIL;
	}
	return RESULT_PASS;
}

/*
 * RFC 7323 Sections 3.2 and 4.3: once Timestamps are negotiated, every
 * non-RST segment carries the option, and an ACK for an in-order segment
 * echoes that segment's TSval in TSecr.  Declining Timestamps in the
 * SYN,ACK is permitted.
 */
static enum result test_tcp_ts_negotiated(const char **why)
{
	struct fixture f;
	struct passive_syn_ack syn_ack;
	const uint16_t peer_port_be = ii_htons(27101);
	uint8_t ts_option[8] = { 0x00, 0x00, 0x20, 0x00, 0, 0, 0, 0 };
	uint8_t *tsopt;
	void *ack;

	if (!fixture_init(&f) ||
			!fixture_passive_open(&f, peer_port_be, -1, 1, 1, &syn_ack))
		return RESULT_FAIL;
	if (!syn_ack.has_ts)
		return RESULT_PASS;
	ts_option[4] = (uint8_t)(syn_ack.ts_val >> 24);
	ts_option[5] = (uint8_t)(syn_ack.ts_val >> 16);
	ts_option[6] = (uint8_t)(syn_ack.ts_val >> 8);
	ts_option[7] = (uint8_t)syn_ack.ts_val;
	ack = passive_data_ack(&f, peer_port_be, &syn_ack, ts_option);
	if (!ack) {
		*why = "received data was not acknowledged";
		return RESULT_FAIL;
	}
	tsopt = option_find(ack, 8);
	if (!tsopt || tsopt[1] != 10) {
		*why = "a data ACK omitted Timestamps after they were negotiated";
		return RESULT_FAIL;
	}
	if (memcmp(&tsopt[6], ts_option, 4)) {
		*why = "the ACK did not echo the TSval of the acknowledged segment";
		return RESULT_FAIL;
	}
	return RESULT_PASS;
}

/*
 * RFC 9293 Sections 3.10.7.1 and 3.10.7.2: an ACK-bearing segment that does
 * not belong to a synchronized connection is answered with
 * <SEQ=SEG.ACK><CTL=RST> whether the port is CLOSED or in LISTEN.  The
 * test backend accepts connections on every port, so this case is chosen
 * because the required response is the same in both states.
 */
static enum result test_tcp_rst_for_stray_ack(const char **why)
{
	static const uint8_t payload[3] = { 1, 2, 3 };
	struct fixture f;
	struct tcp_packet_spec spec;
	void *rst = NULL;
	unsigned int i;

	if (!fixture_init(&f))
		return RESULT_FAIL;
	fixture_incoming_spec(&f, &spec, 500, payload, sizeof(payload));
	spec.src_port_be = ii_htons(28000);
	spec.dst_port_be = ii_htons(9);
	spec.ack_seq = 0x01020304U;
	spec.tcp_flags = TEST_TCP_ACK;
	fixture_deliver(&f, build_tcp_packet(&spec, &f.state));
	fixture_run_timers(&f);
	for (i = 0; i < f.state.out_cnt; i++) {
		void *pkt = f.state.out[i];
		if (PB_IP4(pkt)->proto == 6 && PB_TCP(pkt)->dst_be == ii_htons(28000))
			rst = pkt;
	}
	if (!rst || !PB_TCP_HDR_HAS_RST(rst)) {
		*why = "no RST was sent for an ACK that matches no connection";
		return RESULT_FAIL;
	}
	if (PB_TCP_HDR_HAS_ACK(rst) || PB_TCP_HDR_HAS_SYN(rst) ||
			ii_ntohl(PB_TCP(rst)->seq_be) != 0x01020304U ||
			PB_TCP(rst)->src_be != ii_htons(9) || !checksum_valid(rst)) {
		*why = "the RST was not <SEQ=SEG.ACK><CTL=RST> from the addressed port";
		return RESULT_FAIL;
	}
	return RESULT_PASS;
}

/*
 * RFC 9293 Sections 3.10.7.1 and 3.10.7.2: an incoming RST that matches no
 * connection is discarded; no RST is sent in response to a RST.
 */
static enum result test_tcp_no_rst_for_rst(const char **why)
{
	struct fixture f;
	struct tcp_packet_spec spec;
	unsigned int i;

	if (!fixture_init(&f))
		return RESULT_FAIL;
	fixture_incoming_spec(&f, &spec, 500, NULL, 0);
	spec.src_port_be = ii_htons(28001);
	spec.dst_port_be = ii_htons(9);
	spec.tcp_flags = TEST_TCP_RST;
	fixture_deliver(&f, build_tcp_packet(&spec, &f.state));
	spec.tcp_flags = TEST_TCP_RST | TEST_TCP_ACK;
	spec.ack_seq = 1000;
	fixture_deliver(&f, build_tcp_packet(&spec, &f.state));
	fixture_run_timers(&f);
	for (i = 0; i < f.state.out_cnt; i++)
		if (PB_IP4(f.state.out[i])->proto == 6) {
			*why = "a segment was sent in response to a stray RST";
			return RESULT_FAIL;
		}
	return RESULT_PASS;
}

static const struct ip4_requirement_test tcp_extension_tests[] = {
	{ test_tcp_ws_not_offered, "TCP-WS-1",
			"do not send Window Scale unless the SYN carried it" },
	{ test_tcp_ws_negotiated_window, "TCP-WS-2",
			"advertise windows consistent with the announced shift" },
	{ test_tcp_ts_not_offered, "TCP-TS-1",
			"do not send Timestamps unless the SYN carried them" },
	{ test_tcp_ts_negotiated, "TCP-TS-2",
			"send Timestamps on every segment and echo TSval after negotiation" },
	{ test_tcp_rst_for_stray_ack, "TCP-RST-1",
			"answer an ACK for no connection with <SEQ=SEG.ACK><CTL=RST>" },
	{ test_tcp_no_rst_for_rst, "TCP-RST-2",
			"never answer a RST that matches no connection" },
};

static int tcp_extension_test_main(void)
{
	return requirement_suite_main("TCP extension and reset",
			tcp_extension_tests, ARRAY_LENGTH(tcp_extension_tests));
}

static int ip4_requirement_test_main(void)
{
	return requirement_suite_main("IPv4 host requirements",
			ip4_requirement_tests, ARRAY_LENGTH(ip4_requirement_tests));
}

static void fake_clock_self_test(void)
{
	struct test_state state = { 0 };
	uint32_t t[3];
	uint64_t initial_sec = (1ULL << 32) + 7;

	fake_clock_set_ns(&state, initial_sec * 1000000000ULL + 123456789ULL);
	iip_ops_util_now_ns(t, &state);
	assert(t[0] == 1);
	assert(t[1] == 7);
	assert(t[2] == 123456789U);

	fake_clock_advance_ms(&state, 900);
	fake_clock_advance_sec(&state, 2);
	iip_ops_util_now_ns(t, &state);
	assert(t[0] == 1);
	assert(t[1] == 10);
	assert(t[2] == 23456789U);

	fake_clock_use_real_time(&state);
	assert(!state.use_fake_clock);
	assert(test_event_count(&state, TEST_EVENT_CLOCK, TEST_CLOCK_SET) == 1);
	assert(test_event_count(&state, TEST_EVENT_CLOCK,
			TEST_CLOCK_ADVANCE) == 2);
}

static void packet_builder_self_test(void)
{
	struct test_state state = { 0 };
	struct tcp_packet_spec spec;
	const uint8_t payload[] = { 0xde, 0xad, 0xbe, 0xef };
	void *pkt;
	void *opaque = &state;

	tcp_packet_spec_init(&spec);
	memcpy(spec.src_mac, (uint8_t[]){ 0x02, 1, 2, 3, 4, 5 }, 6);
	memcpy(spec.dst_mac, (uint8_t[]){ 0x04, 6, 7, 8, 9, 10 }, 6);
	spec.src_ip_be = ii_htonl(0xc0000201U);
	spec.dst_ip_be = ii_htonl(0xc6336402U);
	spec.src_port_be = ii_htons(12345);
	spec.dst_port_be = ii_htons(80);
	spec.seq = 100;
	spec.ack_seq = 200;
	spec.tcp_flags = TEST_TCP_ACK | TEST_TCP_PSH;
	spec.payload = payload;
	spec.payload_len = sizeof(payload);
	spec.ip_options[0] = 1;
	spec.ip_options_len = 1;
	tcp_packet_add_nop(&spec);
	tcp_packet_add_mss(&spec, 1200);
	tcp_packet_add_eol(&spec);

	pkt = build_tcp_packet(&spec, opaque);
	assert(iip_ops_pkt_get_len(pkt, opaque) ==
			14 + ii_ntohs(PB_IP4(pkt)->len_be));
	assert((PB_IP4(pkt)->vl & 0x0f) == 6);
	assert(PB_TCP_HDR_LEN(pkt) == 7);
	assert(PB_TCP_PAYLOAD_LEN(pkt) == sizeof(payload));
	assert(!memcmp(PB_TCP_PAYLOAD(pkt), payload, sizeof(payload)));
	assert(PB_TCP_HDR_HAS_ACK(pkt));
	assert(PB_TCP_HDR_HAS_PSH(pkt));
	assert(PB_TCP_OPT(pkt)[6] == 0 && PB_TCP_OPT(pkt)[7] == 0);
	assert(ip4_checksum_valid(pkt));
	assert(checksum_valid(pkt));
	iip_ops_l2_push(pkt, opaque);
	assert(test_event_count(&state, TEST_EVENT_TX_PACKET, 0) == 1);
	free_output(&state);

	spec.corrupt_tcp_checksum = 1;
	pkt = build_tcp_packet(&spec, opaque);
	assert(ip4_checksum_valid(pkt));
	assert(!checksum_valid(pkt));
	iip_ops_pkt_free(pkt, opaque);
}

static void event_log_self_test(void)
{
	struct test_state state = { 0 };
	struct ii_tcp_conn object = { 0 };
	struct ii_tcp_conn *conn = &object;

	fake_clock_set_ns(&state, 1000000000ULL);
	conn->state = II_TCP_STATE_ESTABLISHED;
	test_event_tcp_state_set(&state, conn, conn->state);
	test_event_timer(&state, TEST_TIMER_FAST, 1000);
	test_event_append(&state, TEST_EVENT_CALLBACK, TEST_CALLBACK_CONNECTED,
			&conn, 0, 0, 0, 0);
	assert(test_event_count(&state, TEST_EVENT_STATE_TRANSITION, 0) == 1);
	assert(test_event_count(&state, TEST_EVENT_TIMER, TEST_TIMER_FAST) == 1);
	assert(test_event_count(&state, TEST_EVENT_CALLBACK,
			TEST_CALLBACK_CONNECTED) == 1);
	assert(state.events[1].at_ns == 1000000000ULL);
	test_event_log_clear(&state);
	assert(state.event_count == 0 && state.event_dropped == 0);
}

static int udp_checksum_valid(void *pkt)
{
	struct iip_l4_ip4_pseudo_hdr pseudo;
	uint8_t *b[2];
	uint16_t l[2];
	uint16_t supplied = ii_ntohs(PB_UDP(pkt)->csum_be);

	pseudo.ip4_src_be = PB_IP4(pkt)->src_be;
	pseudo.ip4_dst_be = PB_IP4(pkt)->dst_be;
	pseudo.pad = 0;
	pseudo.proto = 17;
	pseudo.len_be = PB_UDP(pkt)->len_be;
	b[0] = (uint8_t *)&pseudo;
	b[1] = (uint8_t *)PB_UDP(pkt);
	l[0] = sizeof(pseudo);
	l[1] = PB_UDP_TOTAL_LEN(pkt);
	return supplied == test_netcsum16(b, l, 2, supplied);
}

static void *fixture_udp_packet(struct fixture *f, const uint8_t *payload,
		uint16_t payload_len)
{
	void *data = NULL;
	void *pkt;

	if (payload_len) {
		data = iip_ops_pkt_alloc(&f->state);
		assert(data);
		memcpy(iip_ops_pkt_get_data(data, &f->state), payload, payload_len);
		iip_ops_pkt_set_len(data, payload_len, &f->state);
	}
	memcpy(f->state.local_mac, f->peer_mac, 6);
	f->state.local_ip4_be = ii_htonl(f->conn->dst_ip[0]);
	assert(iip_udp_ipv4_ethernet_send_copy(f->ws, f->peer_mac, ii_htonl(f->conn->dst_ip[0]),
			ii_htons(20000), f->local_mac, ii_htonl(f->conn->src_ip[0]),
			ii_htons(10000), 0, data ? iip_ops_pkt_get_data(data, &f->state) : NULL, payload_len, &f->state) == 0);
	iip_ops_pkt_free(data, &f->state);
	assert(f->state.out_cnt == 1);
	pkt = f->state.out[0];
	f->state.out_cnt = 0;
	return pkt;
}

/*
 * Independent one's-complement sum over the IPv4 pseudo header and the UDP
 * datagram, with the checksum field taken as zero.  An odd-length datagram is
 * padded with one zero octet for the computation only.
 */
static uint16_t udp_reference_sum(void *pkt)
{
	const uint8_t *ip = (const uint8_t *)PB_IP4(pkt);
	const uint8_t *udp = (const uint8_t *)PB_UDP(pkt);
	uint16_t udp_len = PB_UDP_TOTAL_LEN(pkt);
	uint32_t sum = 0;
	uint16_t i;

	for (i = 12; i < 20; i += 2)
		sum += (uint32_t)ip[i] << 8 | ip[i + 1];
	sum += 17;
	sum += udp_len;
	for (i = 0; i < udp_len; i += 2) {
		uint16_t hi = udp[i];
		uint16_t lo = i + 1 < udp_len ? udp[i + 1] : 0;
		if (i == 6)
			continue; /* checksum field */
		sum += (uint32_t)hi << 8 | lo;
	}
	while (sum >> 16)
		sum = (sum & 0xffff) + (sum >> 16);
	return (uint16_t)sum;
}

/*
 * RFC 768 and RFC 1122 Section 4.1.3.4: the checksum covers the pseudo header
 * (addresses, protocol, UDP length) and the UDP header and data.  Datagrams
 * with a nonzero, incorrect checksum MUST be silently discarded.
 */
static enum result test_udp_checksum_validation(const char **why)
{
	static const uint8_t payload[7] = { 0xff, 0xff, 0x80, 0x01, 0x7f, 0xfe, 0x55 };
	struct fixture f;
	void *pkt;
	uint16_t expected;

	if (!fixture_init(&f))
		return RESULT_FAIL;
	/* Odd length and carry-producing words exercise padding and folding. */
	pkt = fixture_udp_packet(&f, payload, sizeof(payload));
	expected = (uint16_t)~udp_reference_sum(pkt);
	if (!expected)
		expected = 0xffff;
	if (ii_ntohs(PB_UDP(pkt)->csum_be) != expected) {
		*why = "transmitted UDP checksum does not match the pseudo-header computation";
		return RESULT_FAIL;
	}
	fixture_deliver(&f, pkt);
	if (test_event_count(&f.state, TEST_EVENT_CALLBACK,
			TEST_CALLBACK_UDP_PAYLOAD) != 1) {
		*why = "a UDP datagram with a valid checksum was not delivered";
		return RESULT_FAIL;
	}

	/* Corrupt only the payload: the nonzero checksum is now wrong. */
	test_event_log_clear(&f.state);
	pkt = fixture_udp_packet(&f, payload, sizeof(payload));
	PB_UDP_PAYLOAD(pkt)[0] ^= 0x01;
	fixture_deliver(&f, pkt);
	if (test_event_count(&f.state, TEST_EVENT_CALLBACK,
			TEST_CALLBACK_UDP_PAYLOAD) != 0 ||
			output_count_ethertype(&f.state, 0x0800) != 0) {
		*why = "a UDP datagram with an incorrect checksum was not silently discarded";
		return RESULT_FAIL;
	}

	/* Change only the IPv4 source address: the pseudo header no longer
	 * matches, although the UDP header and data are unchanged. */
	test_event_log_clear(&f.state);
	pkt = fixture_udp_packet(&f, payload, sizeof(payload));
	PB_IP4(pkt)->src_be = ii_htonl(f.conn->dst_ip[0] + 1);
	update_ip4_checksum(pkt);
	fixture_deliver(&f, pkt);
	if (test_event_count(&f.state, TEST_EVENT_CALLBACK,
			TEST_CALLBACK_UDP_PAYLOAD) != 0) {
		*why = "the UDP checksum did not cover the IPv4 pseudo header";
		return RESULT_FAIL;
	}
	free_output(&f.state);
	return RESULT_PASS;
}

/*
 * RFC 768: a transmitted checksum of zero means that no checksum was
 * generated.  Discarding such datagrams is only an optional, configurable
 * behavior (RFC 1122 Section 4.1.3.4), so report a discard as TODO.
 */
static enum result test_udp_zero_checksum_receive(const char **why)
{
	static const uint8_t payload[4] = { 1, 2, 3, 4 };
	struct fixture f;
	void *pkt;

	if (!fixture_init(&f))
		return RESULT_FAIL;
	pkt = fixture_udp_packet(&f, payload, sizeof(payload));
	PB_UDP(pkt)->csum_be = 0;
	fixture_deliver(&f, pkt);
	if (test_event_count(&f.state, TEST_EVENT_CALLBACK,
			TEST_CALLBACK_UDP_PAYLOAD) != 1) {
		*why = "a UDP datagram without a checksum (zero) was discarded";
		return RESULT_TODO;
	}
	return RESULT_PASS;
}

/*
 * RFC 768: if the computed checksum is zero, it is transmitted as all ones
 * (0xffff), because zero on the wire means that no checksum was generated.
 * Choose the last payload word so that the computed checksum is zero.
 */
static enum result test_udp_zero_result_checksum(const char **why)
{
	uint8_t payload[8] = { 0x12, 0x34, 0x56, 0x78, 0x9a, 0xbc, 0, 0 };
	struct fixture f;
	void *pkt;
	uint16_t word;

	if (!fixture_init(&f))
		return RESULT_FAIL;
	pkt = fixture_udp_packet(&f, payload, sizeof(payload));
	word = (uint16_t)~udp_reference_sum(pkt);
	iip_ops_pkt_free(pkt, &f.state);
	payload[6] = (uint8_t)(word >> 8);
	payload[7] = (uint8_t)word;
	pkt = fixture_udp_packet(&f, payload, sizeof(payload));
	if ((uint16_t)~udp_reference_sum(pkt) != 0) {
		*why = "test construction error: computed checksum is not zero";
		return RESULT_FAIL;
	}
	if (ii_ntohs(PB_UDP(pkt)->csum_be) != 0xffff) {
		*why = "a computed UDP checksum of zero was not transmitted as 0xffff";
		return RESULT_FAIL;
	}
	fixture_deliver(&f, pkt);
	if (test_event_count(&f.state, TEST_EVENT_CALLBACK,
			TEST_CALLBACK_UDP_PAYLOAD) != 1) {
		*why = "a UDP datagram carrying checksum 0xffff was not delivered";
		return RESULT_FAIL;
	}
	return RESULT_PASS;
}

/*
 * RFC 1122 Section 4.1.3.1: a UDP datagram for a port with no listener
 * SHOULD be answered with ICMP Destination Unreachable, code 3, quoting the
 * IPv4 header and the first 8 octets of the datagram.  When the datagram is
 * delivered to the application, the API has no closed-port state and the
 * requirement does not apply.
 */
static enum result test_udp_port_unreachable(const char **why)
{
	static const uint8_t payload[4] = { 1, 2, 3, 4 };
	struct fixture f;
	void *pkt, *reply;
	uint8_t quoted[sizeof(struct iip_ip4_hdr) + 8];

	if (!fixture_init(&f))
		return RESULT_FAIL;
	pkt = fixture_udp_packet(&f, payload, sizeof(payload));
	memcpy(quoted, PB_IP4(pkt), sizeof(quoted));
	fixture_deliver(&f, pkt);
	if (test_event_count(&f.state, TEST_EVENT_CALLBACK,
			TEST_CALLBACK_UDP_PAYLOAD) != 0) {
		*why = "the UDP API delivers every datagram to the application; no port is closed";
		return RESULT_SKIP;
	}
	if (output_count_ethertype(&f.state, 0x0800) == 0) {
		*why = "a datagram for a port with no listener was discarded without ICMP Port Unreachable (SHOULD)";
		return RESULT_TODO;
	}
	reply = output_nth_ethertype(&f.state, 0x0800, 0);
	if (PB_IP4(reply)->proto != 1 || PB_ICMP(reply)->type != 3 ||
			PB_ICMP(reply)->code != 3 || !icmp_checksum_valid(reply) ||
			memcmp(PB_ICMP_DATA(reply), quoted, sizeof(quoted))) {
		*why = "the response is not a valid ICMP Port Unreachable quoting the datagram";
		return RESULT_FAIL;
	}
	return RESULT_PASS;
}

static void assert_udp_delivery(const struct test_state *state,
		uint8_t expected, uint16_t payload_len, uint8_t first_payload_byte)
{
	const struct test_event *event;

	assert(test_event_count(state, TEST_EVENT_CALLBACK,
			TEST_CALLBACK_UDP_PAYLOAD) == expected);
	if (!expected)
		return;
	event = test_event_nth(state, TEST_EVENT_CALLBACK,
			TEST_CALLBACK_UDP_PAYLOAD, 0);
	assert(event && event->value[0] == 20000 &&
			event->value[1] == 10000 &&
			event->value[2] == payload_len &&
			event->value[3] == first_payload_byte);
}

static void udp_path_self_test(void)
{
	struct fixture f;
	const uint8_t payload[] = { 0xde, 0xad, 0xbe, 0xef, 0x42 };
	void *pkt;

	assert(fixture_init(&f));
	pkt = fixture_udp_packet(&f, payload, sizeof(payload));
	assert(PB_IP4(pkt)->proto == 17);
	assert(PB_IP4_TOTAL_LEN(pkt) ==
			sizeof(struct iip_ip4_hdr) + sizeof(struct iip_udp_hdr) +
			sizeof(payload));
	assert(PB_UDP_TOTAL_LEN(pkt) == sizeof(struct iip_udp_hdr) +
			sizeof(payload));
	assert(!memcmp(PB_UDP_PAYLOAD(pkt), payload, sizeof(payload)));
	assert(ip4_checksum_valid(pkt));
	assert(udp_checksum_valid(pkt));
	fixture_deliver(&f, pkt);
	assert_udp_delivery(&f.state, 1, sizeof(payload), payload[0]);

	test_event_log_clear(&f.state);
	pkt = fixture_udp_packet(&f, payload, sizeof(payload));
	PB_UDP(pkt)->csum_be ^= ii_htons(1);
	fixture_deliver(&f, pkt);
	assert_udp_delivery(&f.state, 0, 0, 0);

	test_event_log_clear(&f.state);
	pkt = fixture_udp_packet(&f, payload, sizeof(payload));
	PB_UDP(pkt)->len_be = ii_htons(PB_UDP_TOTAL_LEN(pkt) - 1);
	fixture_deliver(&f, pkt);
	assert_udp_delivery(&f.state, 0, 0, 0);
	free_output(&f.state);
}

static void udp_fragment_limit_case(unsigned int fragment_count,
		uint8_t expect_delivery)
{
	struct fixture f;
	uint8_t *payload;
	void *datagram;
	void **fragments;
	uint16_t payload_len;
	uint16_t payload_offset = 0;
	unsigned int i;

	assert(fragment_count > 1);
	assert(fragment_count <= TEST_PKT_MAX);
	assert(fragment_count <= (UINT16_MAX - sizeof(struct iip_udp_hdr)) / 8);
	assert(fixture_init(&f));

	/*
	 * Keep the first fragment large enough to contain both the UDP header and
	 * one payload octet.  Every later fragment is the minimum legal 8 octets.
	 */
	payload_len = (uint16_t)(fragment_count * 8);
	payload = malloc(payload_len);
	fragments = calloc(fragment_count, sizeof(*fragments));
	assert(payload && fragments);
	for (i = 0; i < payload_len; i++)
		payload[i] = (uint8_t)(0xa5U + i);
	datagram = fixture_udp_packet(&f, payload, payload_len);
	assert(PB_IP4_TOTAL_LEN(datagram) - PB_IP4_HDR_LEN(datagram) ==
			(uint16_t)((fragment_count + 1) * 8));

	for (i = 0; i < fragment_count; i++) {
		uint16_t fragment_len = i ? 8 : 16;

		fragments[fragment_count - 1 - i] =
			fixture_ip4_fragment(&f, datagram,
				payload_offset, fragment_len,
				i + 1 < fragment_count);
		payload_offset += fragment_len;
	}
	iip_ops_pkt_free(datagram, &f.state);
	deliver(f.ws, f.local_mac, ii_htonl(f.conn->src_ip[0]), fragments,
			(uint16_t)fragment_count, &f.state);

	assert_udp_delivery(&f.state, expect_delivery, payload_len, payload[0]);
	free(payload);
	free(fragments);
	free_output(&f.state);
}

static void udp_fragment_limit_self_test(void)
{
	_Static_assert(II_CONF_IPV4_FRAG_CNT_MAX + 1 <= TEST_PKT_MAX,
			"fragment limit test exceeds the test packet array");
	udp_fragment_limit_case(II_CONF_IPV4_FRAG_CNT_MAX, 1);
	udp_fragment_limit_case(II_CONF_IPV4_FRAG_CNT_MAX + 1, 0);
}

static void arp_path_self_test(void)
{
	struct fixture f;
	const struct test_event *event;
	void *request, *reply;
	uint32_t sender_ip4_be, target_ip4_be;

	assert(fixture_init(&f));
	test_api_arp_request(f.ws, f.peer_mac, ii_htonl(f.conn->dst_ip[0]),
			ii_htonl(f.conn->src_ip[0]), &f.state);
	assert(f.state.out_cnt == 1);
	request = f.state.out[0];
	f.state.out_cnt = 0;
	assert(ii_ntohs(iip_ops_l2_ethertype_be(request, &f.state)) ==
			0x0806);
	assert(ii_ntohs(PB_ARP(request)->op_be) == 1);
	assert(!memcmp(iip_ops_l2_hdr_dst_ptr(request, &f.state),
			(uint8_t[]){ 0xff, 0xff, 0xff, 0xff, 0xff, 0xff }, 6));
	assert(!memcmp(PB_ARP_HW_SENDER(request), f.peer_mac, 6));
	memcpy(&sender_ip4_be, PB_ARP_IP_SENDER(request),
			sizeof(sender_ip4_be));
	memcpy(&target_ip4_be, PB_ARP_IP_TARGET(request),
			sizeof(target_ip4_be));
	assert(sender_ip4_be == ii_htonl(f.conn->dst_ip[0]));
	assert(target_ip4_be == ii_htonl(f.conn->src_ip[0]));

	fixture_deliver(&f, request);
	assert(f.state.out_cnt == 1);
	reply = f.state.out[0];
	f.state.out_cnt = 0;
	assert(ii_ntohs(PB_ARP(reply)->op_be) == 2);
	assert(!memcmp(iip_ops_l2_hdr_dst_ptr(reply, &f.state),
			f.peer_mac, 6));
	assert(!memcmp(PB_ARP_HW_SENDER(reply), f.local_mac, 6));
	memcpy(&sender_ip4_be, PB_ARP_IP_SENDER(reply),
			sizeof(sender_ip4_be));
	memcpy(&target_ip4_be, PB_ARP_IP_TARGET(reply),
			sizeof(target_ip4_be));
	assert(sender_ip4_be == ii_htonl(f.conn->src_ip[0]));
	assert(target_ip4_be == ii_htonl(f.conn->dst_ip[0]));

	{
		void *input[1] = { reply };
		deliver(f.ws, f.peer_mac, ii_htonl(f.conn->dst_ip[0]), input, 1, &f.state);
	}
	assert(test_event_count(&f.state, TEST_EVENT_CALLBACK,
			TEST_CALLBACK_ARP_REPLY) == 1);
	event = test_event_nth(&f.state, TEST_EVENT_CALLBACK,
			TEST_CALLBACK_ARP_REPLY, 0);
	assert(event && event->value[0] == 2 &&
			event->value[1] == ii_htonl(f.conn->src_ip[0]) &&
			event->value[2] == ii_htonl(f.conn->dst_ip[0]));
	free_output(&f.state);
}


static void api_pump(struct iip_workspace *a, struct test_state *sa,
		struct iip_workspace *b, struct test_state *sb)
{
	uint32_t next;
	for (unsigned int round = 0; round < 8; round++) {
		unsigned int n = sa->out_cnt;
		void *input[TEST_PKT_MAX];
		memcpy(input, sa->out, n * sizeof(*input));
		sa->out_cnt = 0;
		assert(test_api_run(b, sb->local_mac, sb->local_ip4_be, input,
				(uint16_t)n, &next, sb) == n);
		n = sb->out_cnt;
		memcpy(input, sb->out, n * sizeof(*input));
		sb->out_cnt = 0;
		assert(test_api_run(a, sa->local_mac, sa->local_ip4_be, input,
				(uint16_t)n, &next, sa) == n);
		if (!sa->out_cnt && !sb->out_cnt) return;
	}
	assert(!"API smoke link did not become idle");
}

static void current_api_self_test(void)
{
	struct iip_workspace *a = calloc(1, sizeof(*a));
	struct iip_workspace *b = calloc(1, sizeof(*b));
	struct test_state sa = { 0 }, sb = { 0 };
	uint8_t amac[6] = { 2 }, bmac[6] = { 4 };
	uint32_t aip = ii_htonl(0xc0000201U), bip = ii_htonl(0xc6336402U);
	assert(a && b);
	test_workspace_init(a);
	test_workspace_init(b);
	sa.use_fake_clock = sb.use_fake_clock = 1;
	sa.now_ns = sb.now_ns = 1000000000ULL;
	sa.quiet_payload = sb.quiet_payload = 1;
	memcpy(sa.local_mac, amac, 6);
	memcpy(sb.local_mac, bmac, 6);
	sa.local_ip4_be = aip;
	sb.local_ip4_be = bip;
	assert(test_api_connect(a, amac, aip, ii_htons(10000), bmac,
			bip, ii_htons(20000), &sa) == 0);
	uint32_t next;
	assert(test_api_run(a, amac, aip, NULL, 0, &next, &sa) == 0);
	api_pump(a, &sa, b, &sb);
	assert(a->tcp_conns.array[0].state == II_TCP_STATE_ESTABLISHED);
	assert(b->tcp_conns.array[0].state == II_TCP_STATE_ESTABLISHED);
	assert(test_event_count(&sa, TEST_EVENT_CALLBACK, TEST_CALLBACK_CONNECTED) == 1);
	assert(test_event_count(&sb, TEST_EVENT_CALLBACK, TEST_CALLBACK_ACCEPTED) == 1);
	/* Exercise vector send and both receive callbacks through actual frames. */
	void *pkt = iip_ops_pkt_alloc(&sa);
	memcpy(iip_ops_pkt_get_data(pkt, &sa), (uint8_t[]){ 0, 1, 2, 3 }, 4);
	iip_ops_pkt_set_len(pkt, 4, &sa);
	assert(test_api_send(a, &a->tcp_conns.array[0], pkt, 0, &sa) == 0);
	assert(test_api_run(a, amac, aip, NULL, 0, &next, &sa) == 0);
	api_pump(a, &sa, b, &sb);
	assert(sb.payload_byte_count == 4 && sb.next_payload == 4);
	assert(a->tcp_conns.array[0].acked_seq == a->tcp_conns.array[0].seq);
	pkt = iip_ops_pkt_alloc(&sb);
	memcpy(iip_ops_pkt_get_data(pkt, &sb), (uint8_t[]){ 0, 1, 2, 3 }, 4);
	iip_ops_pkt_set_len(pkt, 4, &sb);
	assert(test_api_send(b, &b->tcp_conns.array[0], pkt, 0, &sb) == 0);
	assert(test_api_run(b, bmac, bip, NULL, 0, &next, &sb) == 0);
	api_pump(a, &sa, b, &sb);
	assert(sa.payload_byte_count == 4 && sa.next_payload == 4);
	/* CLOSE-WAIT callback closes the passive endpoint via its connection ID. */
	sb.close_wait.auto_close = 1;
	assert(test_api_close(a, &a->tcp_conns.array[0], &sa) == 0);
	assert(test_api_run(a, amac, aip, NULL, 0, &next, &sa) == 0);
	api_pump(a, &sa, b, &sb);
	assert(sb.close_wait.count == 1);
	assert(a->tcp_conns.array[0].state == II_TCP_STATE_TIME_WAIT);
	assert(b->tcp_conns.array[0].state == II_TCP_STATE_CLOSED);
	free_output(&sa);
	free_output(&sb);
	free(a);
	free(b);
}

static int run_self_tests(void)
{
	static const struct { const char *name; void (*run)(void); } tests[] = {
		{ "fake clock", fake_clock_self_test },
		{ "packet builder", packet_builder_self_test },
		{ "event log", event_log_self_test },
		{ "buffer shortage", buffer_shortage_self_test },
		{ "UDP paths", udp_path_self_test },
		{ "UDP fragment limit", udp_fragment_limit_self_test },
		{ "ARP paths", arp_path_self_test },
		{ "current API connect/data/close", current_api_self_test },
	};
	int failed = 0;
	for (unsigned int i = 0; i < ARRAY_LENGTH(tests); i++) {
		fflush(NULL);
		pid_t child = fork();
		assert(child >= 0);
		if (!child) { alarm(10); tests[i].run(); fflush(NULL); _exit(0); }
		if (!wait_test_child(child, 11000)) { fprintf(stderr, "Self-test failed: %s\n", tests[i].name); failed++; }
	}
	fprintf(stderr, "Self-test summary: %zu passed, %d failed\n", ARRAY_LENGTH(tests) - failed, failed);
	return failed != 0;
}

static int robustness_test_main(void)
{
	static const struct requirement_test tests[] = {
		{ test_invalid_tcp_header_length, "invalid TCP Data Offset" },
		{ test_additional_malformed_boundaries,
			"malformed-input and boundary-value regression coverage" },
		{ test_reproducible_packet_fuzz,
			"reproducible malformed-packet fuzzing" },
		{ test_tcp_state_transition_coverage,
			"extended TCP state-transition regression coverage" },
		{ test_retransmitted_syn_ack_in_established,
			"ESTABLISHED acknowledges a retransmitted SYN+ACK exactly once" },
		{ test_tcp_capacity_failure_is_atomic,
			"multi-segment capacity failure is atomic" },
		{ test_tcp_payload_capacity_failure_frees_clone,
			"payload capacity failure frees the current segment clone" },
		{ test_tcp_capacity_failure_preserves_existing_queue,
			"capacity failure preserves an existing send queue" },
		{ test_zero_effective_send_mss,
			"zero effective MSS closes without marking unsent data as sent" },
	};
	struct test_summary summary = { 0 };
	unsigned int i;

	printf("TAP version 13\n1..%zu\n", ARRAY_LENGTH(tests));
	fflush(stdout);
	for (i = 0; i < ARRAY_LENGTH(tests); i++) {
		const char *why = NULL;
		enum result result = run_isolated_test(tests[i].run, &why);

		if (result == RESULT_PASS) {
			printf("ok %u - ROBUST-%u %s\n", i + 1, i + 1,
					tests[i].description);
		} else if (result == RESULT_SKIP) {
			printf("ok %u - ROBUST-%u %s # SKIP %s\n", i + 1, i + 1,
					tests[i].description, why ? why : "not applicable");
			summary.skipped++;
		} else {
			printf("not ok %u - ROBUST-%u %s%s%s\n", i + 1, i + 1,
					tests[i].description, why ? " - " : "",
					why ? why : "");
			summary.failed++;
		}
		fflush(stdout);
	}
	fprintf(stderr, "Robustness summary: %zu passed, %u failed, %u skipped\n",
			ARRAY_LENGTH(tests) - summary.failed - summary.skipped,
			summary.failed, summary.skipped);
	return summary.failed ? EXIT_FAILURE : EXIT_SUCCESS;
}

static int fast_open_test_main(uint8_t strict)
{
	static const struct requirement_test tests[] = {
		{ test_tcp_fast_open_passive_data,
			"SYN data is delivered once before final ACK" },
		{ test_tcp_fast_open_rejects_unvalidated_data,
			"unvalidated SYN data is not consumed or delivered" },
		{ test_tcp_fast_open_rejects_duplicate_option,
			"duplicate Fast Open options invalidate SYN data" },
		{ test_tcp_fast_open_cookie_generation_disabled,
			"cookie generation can be disabled with length zero" },
		{ test_tcp_fast_open_active_cookie_and_data,
			"active endpoint saves a cookie and sends acknowledged SYN data" },
		{ test_tcp_fast_open_active_rejection_fallback,
			"rejected active SYN data is retransmitted without SYN" },
	};
	unsigned int failed = 0;
	unsigned int unsupported = 0;
	unsigned int i;

	printf("TAP version 13\n1..%zu\n", ARRAY_LENGTH(tests));
	for (i = 0; i < ARRAY_LENGTH(tests); i++) {
		const char *why = NULL;
		enum result result = run_isolated_test(tests[i].run, &why);

		if (result == RESULT_PASS) {
			printf("ok %u - TFO-%u %s\n",
					i + 1, i + 1, tests[i].description);
		} else if (strict || test_process_failed) {
			printf("not ok %u - TFO-%u %s%s%s\n",
					i + 1, i + 1, tests[i].description,
					why ? " - " : "", why ? why : "");
			failed++;
		} else {
			printf("not ok %u - TFO-%u %s"
					" # TODO TCP Fast Open requirement is not satisfied%s%s\n",
					i + 1, i + 1, tests[i].description,
					why ? " - " : "", why ? why : "");
			unsupported++;
		}
	}
	if (failed) {
		fprintf(stderr, "TCP Fast Open capability summary: %u/%zu failed\n",
				failed, ARRAY_LENGTH(tests));
		return EXIT_FAILURE;
	}
	if (unsupported) {
		fprintf(stderr, "TCP Fast Open capability summary: "
				"%u/%zu not supported (TODO)\n",
				unsupported, ARRAY_LENGTH(tests));
		return EXIT_SUCCESS;
	}
	fprintf(stderr, "TCP Fast Open capability summary: supported\n");
	return EXIT_SUCCESS;
}

static int run_test_suites(void)
{
	int legacy_result = legacy_test_main();
	int rfc9293_result = rfc9293_test_main();
	int ip4_result = ip4_requirement_test_main();
	int tcp_extension_result = tcp_extension_test_main();
	int robustness_result = robustness_test_main();
	int fast_open_result = fast_open_test_main(0);

	return legacy_result || rfc9293_result || ip4_result ||
		tcp_extension_result || robustness_result || fast_open_result;
}

int main(int argc, char **argv)
{
	if (argc == 2 && !strcmp(argv[1], "--self-tests"))
		return run_self_tests();
	if (argc == 2 && !strcmp(argv[1], "--fast-open"))
		return fast_open_test_main(1);
	(void)argc;
	(void)argv;
	int self_result = run_self_tests();
	int suite_result = run_test_suites();
	return self_result || suite_result;
}
